    manifest=read(MASTER/'MASTER_ARTIFACT_MANIFEST.json');assert all(file_record(Path(r['path']))==r for r in manifest['artifacts']+manifest['cores']);verified_oracle_contract()
    summary='==================================================\nMASTER ALOHA→G1 SINGLE-VARIABLE A/B RESULTS\n==================================================\n\nSTARTUP PREPARATION\nNatural ARM14 q0 preserved:YES\nDex3:common OPEN, not legacy full28 equality\nCommon duration:0.700s provisional;21prefix frames\nPreparation identical A/B:SAME RULE/DURATION;22/22saved paths,6/6saved joins\n\nRAW CARTESIAN FEASIBILITY\nA reachable:1772/2066\nA certified unreachable:294/2066\nA correction lower mean/p95/max mm:'+str(agap['raw_position_correction_lower_mm'])+'\nB reachable:2036/2066\nB certified unreachable:30/2066\nB correction bounds:'+str(bgap)+'\n\nEXECUTABLE POSITION\nA qualified SOURCE:1/3\nB qualified SOURCE:3/3\nHard collision:0in qualified trajectories;other candidates NOT QUALIFIED\nHard limits:0\nAdaptive branch flags:0;remaining aggregate-step and Cartesian failures reported\n\nFULL6D\nA:NOT RUN\nB:NOT RUN\nPosition/orientation residual:NOT AVAILABLE\n\nDEX3\nMapping/sign/readback/runtime limits/measured violations:NOT RUN\n\nDATASET\nA/B action changes:NOT AUDITED\nRegenerated:NO\nUnintended confounds:NOT AUDITED\n\nACT\nRetraining required:NOT AUDITED\nACT-A/B checkpoints:No new selection\n\nDEV35\nA executed:0/35\nB executed:0/35\nA/B Approach/Grasp/Lift/Handoff/Ownership/Transport/Bin/FULL TASK:NOT AVAILABLE\nB-A:NOT AVAILABLE\nMcNemar:NOT AVAILABLE\n\nMAIN DEV35 FIGURE:NOT GENERATED\nDEV35 RESULT TABLE:NOT GENERATED\nA TOP VIDEO:NOT GENERATED\nA OVERVIEW VIDEO:NOT GENERATED\nB TOP VIDEO:NOT GENERATED\nB OVERVIEW VIDEO:NOT GENERATED\nTRAIN DIAGNOSTIC FIGURE:'+str(diag/'FIGURE_TRAIN_POSITION_DIAGNOSTIC.png')+'\nTRAIN DIAGNOSTIC TABLE:'+str(diag/'TABLE_TRAIN_POSITION_DIAGNOSTIC.md')+'\nFINAL REPORT:'+str(report)+'\nCHATGPT UPDATE:'+str(MASTER/'CHATGPT_UPDATE.md')+'\n\n==================================================\n'+TERMINAL
